(function () {
  'use strict';

  // ── Formatting helpers ──

  function fmtBytes(b) {
    if (b >= 1e9) return (b / 1e9).toFixed(2) + ' GB';
    if (b >= 1e6) return (b / 1e6).toFixed(2) + ' MB';
    if (b >= 1e3) return (b / 1e3).toFixed(1) + ' KB';
    return b + ' B';
  }

  function fmtSecs(s) {
    if (s >= 60) {
      var m = Math.floor(s / 60);
      var sec = (s % 60).toFixed(0);
      return m + 'm ' + sec + 's';
    }
    return s.toFixed(1) + 's';
  }

  function fmtNum(v) { return v.toLocaleString(); }

  // ── Shared chart config ──

  var COLORS = {
    blue: '#4fc3f7',
    green: '#66bb6a',
    orange: '#ffa726',
    red: '#ef5350',
    purple: '#ab47bc',
    cyan: '#26c6da',
    lime: '#9ccc65',
    pink: '#ec407a',
  };

  var AXIS_LABEL = { color: '#8888aa', fontSize: 11 };
  var AXIS_LINE = { lineStyle: { color: '#2a2a4a' } };
  var SPLIT_LINE = { lineStyle: { color: '#1e1e3a', type: 'dashed' } };

  function baseXAxis() {
    return {
      type: 'time',
      axisLabel: AXIS_LABEL,
      axisLine: AXIS_LINE,
      axisTick: { show: false },
    };
  }

  function baseYAxis(name, formatter) {
    return {
      type: 'value',
      name: name,
      nameTextStyle: { color: '#8888aa', fontSize: 11 },
      axisLabel: Object.assign({}, AXIS_LABEL, formatter ? { formatter: formatter } : {}),
      axisLine: { show: false },
      splitLine: SPLIT_LINE,
    };
  }

  function tooltipFormatter(data, valueFmt) {
    return function (params) {
      var idx = params[0].dataIndex;
      var commit = data[idx].commit_short || '';
      var d = new Date(params[0].value[0]);
      var dateStr = d.getFullYear() + '-' +
        String(d.getMonth() + 1).padStart(2, '0') + '-' +
        String(d.getDate()).padStart(2, '0') + ' ' +
        String(d.getHours()).padStart(2, '0') + ':' +
        String(d.getMinutes()).padStart(2, '0');
      var header = '<div style="margin-bottom:6px;font-weight:600">' +
        dateStr + ' <span style="color:#8888aa">(' + commit + ')</span></div>';
      var rows = params.map(function (p) {
        var val = valueFmt ? valueFmt(p.value[1]) : p.value[1];
        return '<span style="display:inline-block;width:8px;height:8px;border-radius:50%;background:' +
          p.color + ';margin-right:6px"></span>' + p.seriesName + ': <strong>' + val + '</strong>';
      }).join('<br/>');
      return header + rows;
    };
  }

  function baseTooltip(data, valueFmt) {
    return {
      trigger: 'axis',
      backgroundColor: '#1a1a2e',
      borderColor: '#2a2a4a',
      textStyle: { color: '#e0e0e0', fontSize: 12 },
      formatter: tooltipFormatter(data, valueFmt),
    };
  }

  function baseLegend() {
    return {
      textStyle: { color: '#8888aa', fontSize: 11 },
      top: 4,
      right: 16,
      itemWidth: 14,
      itemHeight: 8,
    };
  }

  function baseGrid() {
    return { left: 60, right: 24, top: 48, bottom: 36 };
  }

  function dataZoom() {
    return [{ type: 'inside', start: 0, end: 100 }];
  }

  function timeSeries(name, dates, values, color, opts) {
    var paired = dates.map(function (d, i) { return [d, values[i]]; });
    return Object.assign({
      name: name,
      type: 'line',
      data: paired,
      symbol: 'circle',
      symbolSize: 4,
      lineStyle: { width: 2, color: color },
      itemStyle: { color: color },
      emphasis: { focus: 'series' },
    }, opts || {});
  }

  // ── Init chart helper ──

  function initChart(id) {
    var dom = document.getElementById(id);
    return echarts.init(dom, null, { renderer: 'canvas' });
  }

  // ── Summary cards ──

  function renderCards(latest, prev) {
    var container = document.getElementById('summary-cards');
    var m = latest.metrics;

    var cards = [
      { label: 'Binary', value: fmtBytes(m.binary_size_bytes.host_release), prev: prev && prev.metrics.binary_size_bytes.host_release, unit: '', higherBetter: false, raw: m.binary_size_bytes.host_release },
      { label: 'Debug Build', value: fmtSecs(m.build_time_secs.debug_clean), prev: prev && prev.metrics.build_time_secs.debug_clean, unit: '', higherBetter: false, raw: m.build_time_secs.debug_clean },
      { label: 'Effective LOC', value: fmtNum(m.effective_loc), prev: prev && prev.metrics.effective_loc, unit: '', higherBetter: null },
      { label: 'Dependencies', value: fmtNum(m.dependencies.transitive), prev: prev && prev.metrics.dependencies.transitive, unit: '', higherBetter: false },
    ];

    container.innerHTML = cards.map(function (c) {
      var deltaHtml = '';
      if (c.prev != null) {
        var curVal = c.raw != null ? c.raw : parseFloat(c.value.replace(/[^0-9.]/g, ''));
        var prevVal = c.prev;
        var diff = curVal - prevVal;
        if (diff !== 0) {
          var cls = c.higherBetter === null ? 'neutral' : ((diff > 0) === c.higherBetter ? 'up' : 'down');
          var sign = diff > 0 ? '+' : '';
          var display;
          if (c.label === 'Binary') display = sign + fmtBytes(Math.abs(diff));
          else if (c.label.includes('Build')) display = sign + diff.toFixed(1) + 's';
          else display = sign + fmtNum(diff);
          deltaHtml = '<div class="delta ' + cls + '">' + display + '</div>';
        }
      }
      return '<div class="card"><div class="label">' + c.label + '</div><div class="value">' + c.value + '</div>' + deltaHtml + '</div>';
    }).join('');
  }

  // ── Chart builders ──

  function chartBinary(data, dates) {
    var chart = initChart('chart-binary');
    chart.setOption({
      tooltip: baseTooltip(data, fmtBytes),
      legend: baseLegend(),
      grid: baseGrid(),
      dataZoom: dataZoom(),
      xAxis: baseXAxis(),
      yAxis: baseYAxis('Size', function (v) { return fmtBytes(v); }),
      series: [
        timeSeries('release', dates, data.map(function (d) { return d.metrics.binary_size_bytes.host_release; }), COLORS.blue),
      ],
    });
    return chart;
  }

  function chartBuildTime(data, dates) {
    var chart = initChart('chart-build-time');
    chart.setOption({
      tooltip: baseTooltip(data, fmtSecs),
      legend: baseLegend(),
      grid: baseGrid(),
      dataZoom: dataZoom(),
      xAxis: baseXAxis(),
      yAxis: baseYAxis('Time', function (v) { return fmtSecs(v); }),
      series: [
        timeSeries('debug', dates, data.map(function (d) { return d.metrics.build_time_secs.debug_clean; }), COLORS.orange),
      ],
    });
    return chart;
  }

  function chartLoc(data, dates) {
    var chart = initChart('chart-loc');
    chart.setOption({
      tooltip: baseTooltip(data),
      legend: baseLegend(),
      grid: baseGrid(),
      dataZoom: dataZoom(),
      xAxis: baseXAxis(),
      yAxis: baseYAxis('Lines'),
      series: [
        timeSeries('effective LOC', dates, data.map(function (d) { return d.metrics.effective_loc; }), COLORS.cyan, { areaStyle: { color: 'rgba(38,198,218,0.08)' } }),
        timeSeries('vn-runtime (code)', dates, data.map(function (d) { return d.metrics.tokei_rust.vn_runtime.code; }), COLORS.green),
        timeSeries('ring-player (code)', dates, data.map(function (d) { return d.metrics.tokei_rust.ring_player.code; }), COLORS.blue),
        timeSeries('xtask (code)', dates, data.map(function (d) { return d.metrics.tokei_rust.xtask.code; }), COLORS.purple),
      ],
    });
    return chart;
  }

  function chartDeps(data, dates) {
    var chart = initChart('chart-deps');
    chart.setOption({
      tooltip: baseTooltip(data),
      legend: baseLegend(),
      grid: baseGrid(),
      dataZoom: dataZoom(),
      xAxis: baseXAxis(),
      yAxis: baseYAxis('Count'),
      series: [
        timeSeries('transitive', dates, data.map(function (d) { return d.metrics.dependencies.transitive; }), COLORS.orange),
        timeSeries('direct', dates, data.map(function (d) { return d.metrics.dependencies.direct; }), COLORS.blue),
      ],
    });
    return chart;
  }

  // ── Main ──

  fetch('data.json')
    .then(function (r) { return r.json(); })
    .then(function (data) {
      if (!Array.isArray(data)) data = [data];
      if (!data || data.length === 0) {
        document.getElementById('summary-cards').innerHTML =
          '<div class="card" style="grid-column:1/-1"><div class="label">No data yet</div><div class="value">Waiting for first CI run</div></div>';
        return;
      }

      var dates = data.map(function (d) { return new Date(d.date).getTime(); });
      var latest = data[data.length - 1];
      var prev = data.length > 1 ? data[data.length - 2] : null;

      renderCards(latest, prev);

      var charts = [
        chartBinary(data, dates),
        chartBuildTime(data, dates),
        chartLoc(data, dates),
        chartDeps(data, dates),
      ];

      window.addEventListener('resize', function () {
        charts.forEach(function (c) { c.resize(); });
      });
    })
    .catch(function (err) {
      console.error('Failed to load metrics data:', err);
      document.getElementById('summary-cards').innerHTML =
        '<div class="card" style="grid-column:1/-1"><div class="label">Error</div><div class="value">Failed to load data.json</div></div>';
    });
})();

(function () {
  'use strict';

  // ── Formatting helpers ──

  function fmtBytes(b) {
    if (b >= 1e9) return (b / 1e9).toFixed(2) + ' GB';
    if (b >= 1e6) return (b / 1e6).toFixed(2) + ' MB';
    if (b >= 1e3) return (b / 1e3).toFixed(1) + ' KB';
    return b + ' B';
  }

  function fmtSecs(s) {
    if (s >= 60) {
      var m = Math.floor(s / 60);
      var sec = (s % 60).toFixed(0);
      return m + 'm ' + sec + 's';
    }
    return s.toFixed(1) + 's';
  }

  function fmtNum(v) { return v.toLocaleString(); }

  // ── Shared chart config ──

  var COLORS = {
    blue: '#4fc3f7',
    green: '#66bb6a',
    orange: '#ffa726',
    red: '#ef5350',
    purple: '#ab47bc',
    cyan: '#26c6da',
    lime: '#9ccc65',
    pink: '#ec407a',
  };

  var AXIS_LABEL = { color: '#8888aa', fontSize: 11 };
  var AXIS_LINE = { lineStyle: { color: '#2a2a4a' } };
  var SPLIT_LINE = { lineStyle: { color: '#1e1e3a', type: 'dashed' } };

  function baseXAxis() {
    return {
      type: 'time',
      axisLabel: AXIS_LABEL,
      axisLine: AXIS_LINE,
      axisTick: { show: false },
    };
  }

  function baseYAxis(name, formatter) {
    return {
      type: 'value',
      name: name,
      nameTextStyle: { color: '#8888aa', fontSize: 11 },
      axisLabel: Object.assign({}, AXIS_LABEL, formatter ? { formatter: formatter } : {}),
      axisLine: { show: false },
      splitLine: SPLIT_LINE,
    };
  }

  function tooltipFormatter(data, valueFmt) {
    return function (params) {
      var idx = params[0].dataIndex;
      var commit = data[idx].commit_short || '';
      var d = new Date(params[0].value[0]);
      var dateStr = d.getFullYear() + '-' +
        String(d.getMonth() + 1).padStart(2, '0') + '-' +
        String(d.getDate()).padStart(2, '0') + ' ' +
        String(d.getHours()).padStart(2, '0') + ':' +
        String(d.getMinutes()).padStart(2, '0');
      var header = '<div style="margin-bottom:6px;font-weight:600">' +
        dateStr + ' <span style="color:#8888aa">(' + commit + ')</span></div>';
      var rows = params.map(function (p) {
        var val = valueFmt ? valueFmt(p.value[1]) : p.value[1];
        return '<span style="display:inline-block;width:8px;height:8px;border-radius:50%;background:' +
          p.color + ';margin-right:6px"></span>' + p.seriesName + ': <strong>' + val + '</strong>';
      }).join('<br/>');
      return header + rows;
    };
  }

  function baseTooltip(data, valueFmt) {
    return {
      trigger: 'axis',
      backgroundColor: '#1a1a2e',
      borderColor: '#2a2a4a',
      textStyle: { color: '#e0e0e0', fontSize: 12 },
      formatter: tooltipFormatter(data, valueFmt),
    };
  }

  function baseLegend() {
    return {
      textStyle: { color: '#8888aa', fontSize: 11 },
      top: 4,
      right: 16,
      itemWidth: 14,
      itemHeight: 8,
    };
  }

  function baseGrid() {
    return { left: 60, right: 24, top: 48, bottom: 36 };
  }

  function dataZoom() {
    return [{ type: 'inside', start: 0, end: 100 }];
  }

  function timeSeries(name, dates, values, color, opts) {
    var paired = dates.map(function (d, i) { return [d, values[i]]; });
    return Object.assign({
      name: name,
      type: 'line',
      data: paired,
      symbol: 'circle',
      symbolSize: 4,
      lineStyle: { width: 2, color: color },
      itemStyle: { color: color },
      emphasis: { focus: 'series' },
    }, opts || {});
  }

  // ── Init chart helper ──

  function initChart(id) {
    var dom = document.getElementById(id);
    return echarts.init(dom, null, { renderer: 'canvas' });
  }

  // ── Summary cards ──

  function renderCards(latest, prev) {
    var container = document.getElementById('summary-cards');
    var m = latest.metrics;

    var cards = [
      { label: 'Binary', value: fmtBytes(m.binary_size_bytes.ring_player_release || m.binary_size_bytes.host_release), prev: prev && (prev.metrics.binary_size_bytes.ring_player_release || prev.metrics.binary_size_bytes.host_release), unit: '', higherBetter: false, raw: m.binary_size_bytes.ring_player_release || m.binary_size_bytes.host_release },
      { label: 'Debug Build', value: fmtSecs(m.build_time_secs.debug_clean), prev: prev && prev.metrics.build_time_secs.debug_clean, unit: '', higherBetter: false, raw: m.build_time_secs.debug_clean },
      { label: 'Effective LOC', value: fmtNum(m.effective_loc), prev: prev && prev.metrics.effective_loc, unit: '', higherBetter: null },
      { label: 'Dependencies', value: fmtNum(m.dependencies.transitive), prev: prev && prev.metrics.dependencies.transitive, unit: '', higherBetter: false },
    ];

    container.innerHTML = cards.map(function (c) {
      var deltaHtml = '';
      if (c.prev != null) {
        var curVal = c.raw != null ? c.raw : parseFloat(c.value.replace(/[^0-9.]/g, ''));
        var prevVal = c.prev;
        var diff = curVal - prevVal;
        if (diff !== 0) {
          var cls = c.higherBetter === null ? 'neutral' : ((diff > 0) === c.higherBetter ? 'up' : 'down');
          var sign = diff > 0 ? '+' : '';
          var display;
          if (c.label === 'Binary') display = sign + fmtBytes(Math.abs(diff));
          else if (c.label.includes('Build')) display = sign + diff.toFixed(1) + 's';
          else display = sign + fmtNum(diff);
          deltaHtml = '<div class="delta ' + cls + '">' + display + '</div>';
        }
      }
      return '<div class="card"><div class="label">' + c.label + '</div><div class="value">' + c.value + '</div>' + deltaHtml + '</div>';
    }).join('');
  }

  // ── Chart builders ──

  function chartBinary(data, dates) {
    var chart = initChart('chart-binary');
    chart.setOption({
      tooltip: baseTooltip(data, fmtBytes),
      legend: baseLegend(),
      grid: baseGrid(),
      dataZoom: dataZoom(),
      xAxis: baseXAxis(),
      yAxis: baseYAxis('Size', function (v) { return fmtBytes(v); }),
      series: [
        timeSeries('release', dates, data.map(function (d) { return d.metrics.binary_size_bytes.host_release; }), COLORS.blue),
      ],
    });
    return chart;
  }

  function chartBuildTime(data, dates) {
    var chart = initChart('chart-build-time');
    chart.setOption({
      tooltip: baseTooltip(data, fmtSecs),
      legend: baseLegend(),
      grid: baseGrid(),
      dataZoom: dataZoom(),
      xAxis: baseXAxis(),
      yAxis: baseYAxis('Time', function (v) { return fmtSecs(v); }),
      series: [
        timeSeries('debug', dates, data.map(function (d) { return d.metrics.build_time_secs.debug_clean; }), COLORS.orange),
      ],
    });
    return chart;
  }

  function chartLoc(data, dates) {
    var chart = initChart('chart-loc');
    chart.setOption({
      tooltip: baseTooltip(data),
      legend: baseLegend(),
      grid: baseGrid(),
      dataZoom: dataZoom(),
      xAxis: baseXAxis(),
      yAxis: baseYAxis('Lines'),
      series: [
        timeSeries('effective LOC', dates, data.map(function (d) { return d.metrics.effective_loc; }), COLORS.cyan, { areaStyle: { color: 'rgba(38,198,218,0.08)' } }),
        timeSeries('vn-runtime (code)', dates, data.map(function (d) { return d.metrics.tokei_rust.vn_runtime.code; }), COLORS.green),
        timeSeries('ring-player (code)', dates, data.map(function (d) { return d.metrics.tokei_rust.ring_player.code; }), COLORS.blue),
        timeSeries('xtask (code)', dates, data.map(function (d) { return d.metrics.tokei_rust.xtask.code; }), COLORS.purple),
      ],
    });
    return chart;
  }

  function chartDeps(data, dates) {
    var chart = initChart('chart-deps');
    chart.setOption({
      tooltip: baseTooltip(data),
      legend: baseLegend(),
      grid: baseGrid(),
      dataZoom: dataZoom(),
      xAxis: baseXAxis(),
      yAxis: baseYAxis('Count'),
      series: [
        timeSeries('transitive', dates, data.map(function (d) { return d.metrics.dependencies.transitive; }), COLORS.orange),
        timeSeries('direct', dates, data.map(function (d) { return d.metrics.dependencies.direct; }), COLORS.blue),
      ],
    });
    return chart;
  }

  // ── Main ──

  fetch('data.json')
    .then(function (r) { return r.json(); })
    .then(function (data) {
      if (!Array.isArray(data)) data = [data];
      if (!data || data.length === 0) {
        document.getElementById('summary-cards').innerHTML =
          '<div class="card" style="grid-column:1/-1"><div class="label">No data yet</div><div class="value">Waiting for first CI run</div></div>';
        return;
      }

      var dates = data.map(function (d) { return new Date(d.date).getTime(); });
      var latest = data[data.length - 1];
      var prev = data.length > 1 ? data[data.length - 2] : null;

      renderCards(latest, prev);

      var charts = [
        chartBinary(data, dates),
        chartBuildTime(data, dates),
        chartLoc(data, dates),
        chartDeps(data, dates),
      ];

      window.addEventListener('resize', function () {
        charts.forEach(function (c) { c.resize(); });
      });
    })
    .catch(function (err) {
      console.error('Failed to load metrics data:', err);
      document.getElementById('summary-cards').innerHTML =
        '<div class="card" style="grid-column:1/-1"><div class="label">Error</div><div class="value">Failed to load data.json</div></div>';
    });
})();

/**
 * Ring Engine Debug MCP Server
 *
 * Thin MCP wrapper over the debug HTTP REST API embedded in host-dioxus.
 * Runs as a stdio MCP server — Claude Code connects via mcpServers config.
 */

import { McpServer } from "@modelcontextprotocol/sdk/server/mcp.js";
import { StdioServerTransport } from "@modelcontextprotocol/sdk/server/stdio.js";
import { z } from "zod";

const BASE_URL = `http://127.0.0.1:${process.env.RING_DEBUG_PORT || 9876}`;

// ── HTTP helpers ─────────────────────────────────────────────────────────────

async function httpGet(path) {
  const res = await fetch(`${BASE_URL}${path}`);
  if (!res.ok) {
    const text = await res.text();
    throw new Error(`HTTP ${res.status}: ${text}`);
  }
  return res.json();
}

async function httpPost(path, body = undefined) {
  const opts = {
    method: "POST",
    headers: { "Content-Type": "application/json" },
  };
  if (body !== undefined) {
    opts.body = JSON.stringify(body);
  }
  const res = await fetch(`${BASE_URL}${path}`, opts);
  if (!res.ok) {
    const text = await res.text();
    throw new Error(`HTTP ${res.status}: ${text}`);
  }
  return res.json();
}

function jsonText(obj) {
  return JSON.stringify(obj, null, 2);
}

// ── MCP Server ───────────────────────────────────────────────────────────────

const server = new McpServer({
  name: "ring-debug",
  version: "0.1.0",
});

// ── Tools: State Queries ─────────────────────────────────────────────────────

server.tool("ping", "Check if the game is running and get basic status", {}, async () => {
  try {
    const data = await httpGet("/api/ping");
    return { content: [{ type: "text", text: jsonText(data) }] };
  } catch (e) {
    return {
      content: [{ type: "text", text: `Game not reachable: ${e.message}` }],
      isError: true,
    };
  }
});

server.tool(
  "get_game_state",
  "Get full game state: render state, waiting status, playback mode, screen",
  {},
  async () => {
    const data = await httpGet("/api/state");
    return { content: [{ type: "text", text: jsonText(data) }] };
  },
);

server.tool(
  "get_dialogue",
  "Get current dialogue state: speaker, text, typewriter progress, NVL entries",
  {},
  async () => {
    const data = await httpGet("/api/state/dialogue");
    return { content: [{ type: "text", text: jsonText(data) }] };
  },
);

server.tool(
  "get_scene",
  "Get visual scene state: background, characters, transitions, effects",
  {},
  async () => {
    const data = await httpGet("/api/state/scene");
    return { content: [{ type: "text", text: jsonText(data) }] };
  },
);

server.tool(
  "get_choices",
  "Get current choice options (only meaningful when waiting for choice)",
  {},
  async () => {
    const data = await httpGet("/api/state/choices");
    return { content: [{ type: "text", text: jsonText(data) }] };
  },
);

server.tool("get_audio", "Get audio state: BGM, SFX", {}, async () => {
  const data = await httpGet("/api/state/audio");
  return { content: [{ type: "text", text: jsonText(data) }] };
});

// ── Tools: Actions ───────────────────────────────────────────────────────────

server.tool("click", "Click to advance dialogue (equivalent to mouse click / Enter)", {}, async () => {
  const data = await httpPost("/api/click");
  return { content: [{ type: "text", text: jsonText(data) }] };
});

server.tool(
  "choose",
  "Select a choice option by index (0-based)",
  { index: z.number().int().min(0).describe("Choice index (0-based)") },
  async ({ index }) => {
    const data = await httpPost("/api/choose", { index });
    return { content: [{ type: "text", text: jsonText(data) }] };
  },
);

server.tool(
  "advance",
  "Click multiple times until a meaningful wait state (choice, signal, etc.) or max_clicks reached",
  {
    max_clicks: z
      .number()
      .int()
      .min(1)
      .max(100)
      .default(10)
      .describe("Maximum number of clicks (default 10, max 100)"),
  },
  async ({ max_clicks }) => {
    const data = await httpPost("/api/advance", { max_clicks });
    return { content: [{ type: "text", text: jsonText(data) }] };
  },
);

server.tool(
  "navigate",
  "Switch host screen (title, ingame, save, load, settings, history)",
  {
    screen: z
      .string()
      .describe("Target screen: title, ingame, ingamemenu, save, load, settings, history"),
  },
  async ({ screen }) => {
    const data = await httpPost("/api/navigate", { screen });
    return { content: [{ type: "text", text: jsonText(data) }] };
  },
);

server.tool(
  "start_game",
  "Start a new game from a script file, optionally at a specific label",
  {
    script: z.string().optional().describe("Script path (defaults to config start_script_path)"),
    label: z.string().optional().describe("Jump to this label after loading"),
  },
  async ({ script, label }) => {
    const body = {};
    if (script) body.script = script;
    if (label) body.label = label;
    const data = await httpPost("/api/start_game", body);
    return { content: [{ type: "text", text: jsonText(data) }] };
  },
);

server.tool(
  "set_playback_mode",
  "Set playback mode: normal, auto, or skip",
  {
    mode: z.string().describe("Playback mode: normal, auto, skip"),
  },
  async ({ mode }) => {
    const data = await httpPost("/api/playback_mode", { mode });
    return { content: [{ type: "text", text: jsonText(data) }] };
  },
);

// ── Tools: Screenshot ────────────────────────────────────────────────────────

server.tool(
  "screenshot",
  "Capture a screenshot of the current game view (returns base64 PNG image)",
  {},
  async () => {
    const data = await httpGet("/api/screenshot");
    if (data.data_base64) {
      return {
        content: [
          {
            type: "image",
            data: data.data_base64,
            mimeType: "image/png",
          },
        ],
      };
    }
    return {
      content: [{ type: "text", text: jsonText(data) }],
      isError: true,
    };
  },
);

// ── Tools: Diagnostics ───────────────────────────────────────────────────────

server.tool(
  "check_transitions",
  "Check if any transitions or animations are currently in progress",
  {},
  async () => {
    const data = await httpGet("/api/diag/transitions");
    return { content: [{ type: "text", text: jsonText(data) }] };
  },
);

server.tool(
  "check_typewriter",
  "Check typewriter animation progress (visible chars, total, completion)",
  {},
  async () => {
    const data = await httpGet("/api/diag/typewriter");
    return { content: [{ type: "text", text: jsonText(data) }] };
  },
);

// ── Start ────────────────────────────────────────────────────────────────────

const transport = new StdioServerTransport();
await server.connect(transport);

