fn test_position_from_str() {
    assert_eq!(Position::from_str("left").ok(), Some(Position::Left));
    assert_eq!(Position::from_str("LEFT").ok(), Some(Position::Left));
    assert_eq!(Position::from_str("center").ok(), Some(Position::Center));
