    assert!(is_table_separator("| --- | --- |"));
    assert!(is_table_separator("|---|---|"));
    assert!(is_table_separator("| :---: | ---: |"));
    // `/` 字符不是合法分隔符内容
    assert!(!is_table_separator("| /-- | /-- |"));
    assert!(!is_table_separator("| / | / |"));
}

