#[test]
fn test_nested_if_endif_parsed_correctly() {
    // 变异体：`*depth -= 1` → `*depth += 1` / `*depth /= 1`
    // 嵌套的 if/endif 必须能正确闭合，不报 unclosed 错误
    let script = parse_ok("if $a == 1\nif $b == 2\n角色：\"内嵌\"\nendif\nendif\n");
    // 整个双层 if/endif 解析为一个 Conditional 节点
    assert_eq!(script.nodes.len(), 1);
    assert!(
        matches!(&script.nodes[0], ScriptNode::Conditional { .. }),
        "嵌套 if/endif 应解析为 Conditional 节点"
    );
}

#[test]
fn test_triple_nested_if_endif() {
    // 三层嵌套，更彻底验证深度计数正确性
    let script = parse_ok("if $a == 1\nif $b == 2\nif $c == 3\n：\"深层\"\nendif\nendif\nendif\n");
    assert_eq!(script.nodes.len(), 1);
    assert!(matches!(&script.nodes[0], ScriptNode::Conditional { .. }));
}

