#[test]
fn test_reset_state_clears_warnings_between_parses() {
    // 变异体：`reset_state` 的函数体被替换为 `()`，warnings 不清除
    let mut parser = Parser::new();
    // 第一次解析：产生一条警告（未知行）
    let _script1 = parser.parse("test", "??? 无法识别的行").unwrap();
    assert_eq!(parser.warnings().len(), 1, "第一次解析应产生 1 条警告");
    // 第二次解析：完全合法，不产生警告
    let _script2 = parser.parse("test", "角色：\"正常对话\"").unwrap();
    assert_eq!(
        parser.warnings().len(),
        0,
        "第二次解析后 warnings 应被 reset_state 清空"
    );
}

