#[test]
fn test_old_label_double_star_rejected_with_message() {
    // 变异体：line.len() - 2 → line.len() / 2
    // 确认 **label** 语法被明确拒绝（而不是被截断或忽略）
    let err = parse_err("**old_label**");
    assert!(matches!(err, crate::error::ParseError::InvalidLine { .. }));
    let msg = format!("{err:?}");
    assert!(
        msg.contains("old_label"),
        "错误信息应包含旧标签名称，实际：{msg}"
    );
