#[test]
fn test_pause_exact_match_vs_prefix() {
    // 变异体：`line.len() == 5` 与空白检查
    // "pause" 精确匹配应解析为 Pause
    let node = parse_single_node("pause");
    assert_eq!(node, ScriptNode::Pause);

    // "pause " 带尾空格也应解析为 Pause（尾部空白字节检测）
    let node2 = parse_single_node("pause   ");
    assert_eq!(node2, ScriptNode::Pause);

    // "pauseX" 不应被当作 pause 指令（fallthrough 到对话/警告路径）
    // 这行内容不是合法对话也不是已知指令，应产生警告而非 Pause
    let mut parser = Parser::new();
    let script = parser.parse("test", "pauseX").unwrap();
    assert!(
        !matches!(script.nodes.first(), Some(ScriptNode::Pause)),
        "pauseX 不应被误识别为 pause 指令"
    );
}

