    // 引号内的冒号不应触发命名参数分割
    let args = parse_transition_args(r#"mask: "rule:a.png""#).unwrap();
    assert_eq!(args.len(), 1);
    assert_eq!(args[0].0, Some("mask".to_string()));
    assert!(
        matches!(&args[0].1, crate::command::TransitionArg::String(s) if s == "rule:a.png"),
        "引号内的冒号应被视为值的一部分，实际：{:?}",
        args[0].1
    );
}

#[test]
fn test_parse_named_arg_single_quoted_value_with_colon() {
    // 变异体：`ch == '"' || ch == '\''` → `&&`，需要测试单引号路径
    let args = parse_transition_args(r#"easing: 'ease:in'"#).unwrap();
    assert_eq!(args.len(), 1);
    assert_eq!(args[0].0, Some("easing".to_string()));
    assert!(
        matches!(&args[0].1, crate::command::TransitionArg::String(s) if s == "ease:in"),
        "单引号内的冒号应被视为值的一部分，实际：{:?}",
        args[0].1
    );
}

