/// 验证 ChangeScene with rule mask 参数被 executor 正确透传（覆盖 k == "mask" 变异）
#[test]
fn test_executor_change_scene_rule_mask_param_preserved() {
    use crate::{
        command::{Transition, TransitionArg},
        script::ast::ScriptNode,
    };

    // 构造一个带 rule 过渡（含 mask 参数）的 ChangeScene 节点
    let rule_transition = Transition::with_named_args(
        "rule",
        vec![(
            Some("mask".to_string()),
            TransitionArg::String("masks/wipe.png".to_string()),
        )],
    );

    let script = Script::new(
        "test",
        vec![ScriptNode::ChangeScene {
            path: "bg_new.png".to_string(),
            transition: Some(rule_transition),
        }],
        "",
    );
    let mut runtime = VNRuntime::new(script);

    // 执行节点，获取命令
    let (commands, _waiting) = runtime.tick(None).unwrap();
    assert_eq!(commands.len(), 1, "应产生 1 个命令");

    // 验证 ChangeScene 命令携带了正确的 mask 参数
    if let Command::ChangeScene {
        path,
        transition: Some(t),
    } = &commands[0]
    {
        assert_eq!(path, "bg_new.png");
        assert_eq!(t.name, "rule");
        assert_eq!(
            t.get_named("mask"),
            Some(&TransitionArg::String("masks/wipe.png".to_string())),
            "mask 参数应原样透传到 ChangeScene 命令"
        );
    } else {
        panic!(
            "Expected ChangeScene command with transition，实际：{:?}",
            commands[0]
        );
    }
}

