0	//! # 阶段 1：块识别
1	//!
2	//! 将原始文本按行分组为块（单行、表格、条件块）。
3	
4	use super::helpers::starts_with_ignore_case;
5	
6	type ConditionalState = (Vec<(String, usize)>, usize, usize); // (lines, start_line, depth)
7	
8	/// 块类型（阶段 1 输出）
9	#[derive(Debug, Clone)]
10	pub(crate) enum Block {
11	    /// 单行内容
12	    SingleLine { line: String, line_number: usize },
13	    /// 表格块（选择分支）
14	    Table {
15	        lines: Vec<String>,
16	        start_line: usize,
17	    },
18	    /// 条件块（if/elseif/else/endif）
19	    Conditional {
20	        /// 原始行列表 (line, `line_number`)
21	        lines: Vec<(String, usize)>,
22	        start_line: usize,
23	    },
24	}
25	
26	impl Block {
27	    /// 获取块的起始行号
28	    pub(crate) fn start_line(&self) -> usize {
29	        match self {
30	            Block::SingleLine { line_number, .. } => *line_number,
31	            Block::Table { start_line, .. } | Block::Conditional { start_line, .. } => *start_line,
32	        }
33	    }
34	}
35	
36	/// 识别文本中的块
37	pub(crate) fn recognize_blocks(text: &str) -> Vec<Block> {
38	    let mut blocks = Vec::new();
39	    let mut current_table: Option<(Vec<String>, usize)> = None;
40	    let mut current_conditional: Option<ConditionalState> = None;
41	
42	    for (line_idx, line) in text.lines().enumerate() {
43	        let line_number = line_idx + 1;
44	        let trimmed = line.trim();
45	
46	        // 检查是否是条件语句
47	        let is_if = starts_with_ignore_case(trimmed, "if ");
48	        let is_endif = trimmed.eq_ignore_ascii_case("endif");
49	
50	        // 处理条件块
51	        if let Some((ref mut lines, _start, ref mut depth)) = current_conditional {
52	            // 嵌套 if
53	            if is_if {
54	                *depth += 1;
55	            }
56	
57	            lines.push((trimmed.to_string(), line_number));
58	
59	            // endif
60	            if is_endif {
61	                if *depth > 0 {
62	                    *depth -= 1;
63	                } else {
64	                    // 条件块结束（depth==0 时必有对应的 if 已设置 current_conditional）
65	                    let (lines, start, _) = current_conditional
66	                        .take()
67	                        .expect("invariant: endif at depth 0 implies current_conditional set");
