#[test]
fn test_nested_if_endif_followed_by_content() {
    let script = parse_ok(
        "if $a == 1\nif $b == 2\n角色：\"内嵌\"\nendif\nendif\n角色：\"外部\"",
    );
    assert_eq!(
        script.nodes.len(),
        2,
        "应有 Conditional + Dialogue 两个顶层节点"
    );
    assert!(matches!(&script.nodes[0], ScriptNode::Conditional { .. }));
    assert!(matches!(
        &script.nodes[1],
        ScriptNode::Dialogue { content, .. } if content == "外部"
    ));
}

